package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Objects;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * On create, rejects the owner when another owner already shares its last name and address
 * (compared case-insensitively with collapsed whitespace). Skipped when the request opts in
 * via {@code sharesHousehold=true}.
 */
public class EnsureUniqueOwnerHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        String household = household(owner);
        owner.setHouseholdId(Integer.toHexString(household.hashCode()).toUpperCase());
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (!Objects.equals(existing.getId(), owner.getId())
                    && household.equals(household(existing))) {
                throw new DuplicateHouseholdException(
                        "Another owner already shares this last name and address");
            }
        }
    }

    private static String household(Owner owner) {
        return normalize(owner.getLastName()) + '\n' + normalize(owner.getAddress());
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}
=== NormalizeOwnerTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * On create, rewrites the telephone into E.164 form. A leading '+' keeps the given
 * country code; otherwise '+61' is assumed and a single leading '0' is dropped from the
 * national digits. Spaces, dashes and brackets are stripped, and 8 to 15 digits must
 * follow the '+'. Mutates the built {@link Owner} in place so later steps store and
 * return the E.164 value.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val Owner owner) throws InvalidTelephoneException {
        String raw = owner.getTelephone() == null ? "" : owner.getTelephone().trim();
        String digits = raw.replaceAll("[^0-9]", "");
        String e164;
        if (raw.startsWith("+")) {
            e164 = "+" + digits;
        } else {
            e164 = "+61" + (digits.startsWith("0") ? digits.substring(1) : digits);
        }
        int count = e164.length() - 1;
        if (count < 8 || count > 15) {
            throw new InvalidTelephoneException("Telephone cannot form a valid E.164 number");
        }
        if (e164.startsWith("+61") && count - 2 != 9) {
            throw new InvalidTelephoneException("Telephone needs 9 national digits for +61");
        }
        if (e164.startsWith("+1") && count - 1 != 10) {
            throw new InvalidTelephoneException("Telephone needs 10 national digits for +1");
        }
        owner.setTelephone(e164);
    }
}
